<div class="page-heading"><div><div class="eyebrow">Administrasi</div><h1>Akun petugas</h1><p>Kelola akses petugas berdasarkan tugasnya. Nonaktifkan akun yang tidak lagi digunakan.</p></div></div>
<div class="admin-two-col"><section class="card admin-panel"><div class="panel-heading"><div><h2>Daftar petugas</h2><p><?= count($staff) ?> akun internal</p></div></div>
<?php if ($staff): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Nama</th><th>Peran</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach ($staff as $person): ?><tr><td data-label="Nama"><strong><?= e($person->full_name) ?></strong><small><?= e($person->email) ?></small></td><td data-label="Peran"><?= e($person->role_name) ?></td><td data-label="Status"><span class="badge <?= $person->account_status === 'active' ? 'success' : 'danger' ?>"><?= $person->account_status === 'active' ? 'Aktif' : 'Nonaktif' ?></span></td><td data-label="Tindakan"><?php if ((int) $person->id !== (int) $current_user->id && $person->account_status === 'active'): ?><form method="post" action="<?= site_url('staff/deactivate/' . $person->id) ?>" onsubmit="return confirm('Nonaktifkan akun ini?')"><?= form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()) ?><button class="text-button" type="submit">Nonaktifkan</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="table-empty">Belum ada akun petugas.</div><?php endif; ?></section>
<aside><section class="card detail-card"><h2>Buat akun baru</h2><p class="muted small">Bagikan kredensial awal melalui saluran internal yang aman.</p><form method="post" action="<?= site_url('petugas/akun') ?>"><?= form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()) ?><label>Nama lengkap<input name="full_name" required minlength="3" maxlength="160"></label><label>Email<input type="email" name="email" required></label><label>Peran<select name="role_code" required><option value="verifier">Verifikator</option><option value="technician">Petugas teknis</option><option value="coordinator">Koordinator</option><option value="issuer">Pejabat penerbit</option></select></label><label>Kata sandi awal<input type="password" name="password" minlength="12" maxlength="72" required></label><button class="button primary full" type="submit">Buat akun petugas</button></form></section></aside></div>
